//////
// june elva, 2025 february 02
//////
// what lies beyond the entrance...?
// just trying to see what's out there.
//
// ... AKA a mess of expressions, operators, and coefficients
// randomly explored like an earthworm to find interesting dirt.
// winding up the values and then unwinding them again. different.
// seeking, prying into a dimension of limitations and extrusion,
// the walls of which seem to contain the information for continued
// exploration through this shifting, symmetrical maze of numbers.
//

#define REWIND 232.0
#define SLOW 0.2
#define FADE 0.000000000000001

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord.xy / iResolution.xy * 1.2 + vec2(-0.04);
    vec2 ouv = uv;
    float time = iTime;
    float seed = REWIND + SLOW * time;    
    uv = pow(uv, vec2(uv * seed));
    uv.x = tan(uv.x) / uv.y;
    uv.y = tan(uv.y) / uv.x;
    float g = uv.y + uv.y * FADE;
    vec3 c1 = vec3(-g, 0.0, 0.0);
    vec3 c2 = vec3(0.0, 0.0, g);
    vec3 col = mix(c1, c2, (c1 + c2) * uv.yxy);
    float ligh = dot(col.rb + col.rb, vec2(0.01 * ouv.x * sin(time)));
    col = pow(col / ligh, vec3(0.03)) + (uv.y * FADE);
    col.g = clamp(0.5 - col.g, 0.0, 0.9);
    col *= texture(iChannel0, 1.0 - col.rb).rgb;
    fragColor = vec4(col.rbg, 1.0);
}

